import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CWvfYWS8.js";import"./chunks/assets.Bz7j3IzC.js";var i=JSON.parse(`{"title":"内存控制器策略与工具","description":"","frontmatter":{},"headers":[],"relativePath":"zh/ch012.md","filePath":"zh/ch012.md"}`),a={name:`zh/ch012.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="内存控制器策略与工具" tabindex="-1">内存控制器策略与工具 <a class="header-anchor" href="#内存控制器策略与工具" aria-label="Permalink to “内存控制器策略与工具”">​</a></h1><p>以下章节介绍的方法和工具共同构成了一套一致的架构方法，用于提高整个集群的内存利用率。</p><h2 id="内存过量分配" tabindex="-1">内存过量分配 <a class="header-anchor" href="#内存过量分配" aria-label="Permalink to “内存过量分配”">​</a></h2><p>内存过量分配——为进程承诺比系统总内存更多的内存——是提高内存利用率的一项关键技术。它允许系统托管并运行更多应用程序，其假设是并非所有分配的内存都会在同一时间被需要。当然，这一假设并不总是成立；当需求超过可用内存总量时，系统 OOM 处理程序会尝试通过杀死一些进程来回收内存。</p><p>这些不可避免的内存溢出在处理上可能代价高昂，但在一个系统上托管更多服务所带来的节省，超过了偶尔发生 OOM 事件的开销。通过适当的平衡，这种场景可以转化为更高的效率和更低的成本。</p><h2 id="基于压力的减载" tabindex="-1">基于压力的减载 <a class="header-anchor" href="#基于压力的减载" aria-label="Permalink to “基于压力的减载”">​</a></h2><p>减载是一种通过临时拒绝新请求来避免系统过载和崩溃的技术。其理念是：如果系统拒绝少量请求并继续运行，而不是接受所有请求并因资源不足而崩溃，那么所有负载都将得到更好的服务。</p><p>在最近的一项测试中，Facebook 一个运行异步作业的团队（称为 Async）将内存压力作为减载策略的一部分，以降低 OOM 的发生频率。</p><p>Async 层级并行运行许多短生命周期作业。由于此前无法得知系统距离触发 OOM 处理程序有多近，Async 主机经历了过多的 OOM kill。</p><p>利用内存压力作为总体内存健康状况的主动指标，Async 服务器现在可以在执行每个作业之前估算系统是否有足够内存将作业运行至完成。当内存压力超过指定阈值时，系统会忽略进一步的请求，直到条件稳定下来。</p><p>该图展示了 async 如何响应内存压力变化：当 <code>memory.full</code>（橙色）飙升时，async 将作业减载回 async 调度器，如蓝色 <code>async_execution_decision</code> 线所示。</p><p><img src="/p002/ch01/002.png" alt="" width="2684" height="1340"></p><p>结果非常显著：基于内存压力的减载减少了 Async 层级中的内存溢出，并将吞吐量提高了 25%。这使 Async 团队能够用内存更少的服务器替换较大的服务器，同时将 OOM 控制在可控范围内。</p><h2 id="oomd——基于内存压力的-oom" tabindex="-1">oomd——基于内存压力的 OOM <a class="header-anchor" href="#oomd——基于内存压力的-oom" aria-label="Permalink to “oomd——基于内存压力的 OOM”">​</a></h2><p><a href="https://facebookincubator.github.io/oomd" target="_blank" rel="noreferrer">oomd</a> 是一种新的用户空间工具，类似于内核 OOM 处理程序，但它使用内存压力来更好地控制进程何时开始被杀死，以及选择哪些进程。</p><p>内核 OOM 处理程序的主要工作是保护内核；它并不关心确保工作负载的进展或健康。因此，在其运行时机和方式方面并不理想：</p><ul><li><p>它只有在多次尝试分配内存失败后才开始杀死进程，即问题已经发生之后。</p></li><li><p>它使用原始启发式方法选择要杀死的进程，通常杀死释放内存最多的那个进程。</p></li><li><p>当系统发生抖动时，它可能根本无法启动：内存利用率保持在正常范围内，但工作负载没有进展，而 OOM killer 永远不会被调用来清理混乱。</p></li></ul><p>由于缺乏对进程上下文或目的的了解，OOM killer 甚至可能杀死关键系统进程：当这种情况发生时，系统就失去了，唯一的解决方案是重启，丢失正在运行的所有内容，并需要数十分钟来恢复主机。</p><p>oomd 使用内存压力来监控内存短缺，可以通过暂停一些任务来挺过波动，或通过执行优雅的应用关闭并安排重启，从而更主动、更温和地处理不断增长的压力。</p><p>在最近的测试中，oomd 开箱即用地优于内核 OOM killer，目前已在 Facebook 的多个层级中部署到生产环境。</p><h3 id="案例研究-facebook-的-oomd" tabindex="-1">案例研究：Facebook 的 oomd <a class="header-anchor" href="#案例研究-facebook-的-oomd" aria-label="Permalink to “案例研究：Facebook 的 oomd”">​</a></h3><p>请参阅此<a href="https://facebookincubator.github.io/oomd/docs/oomd-casestudy.html" target="_blank" rel="noreferrer">案例研究</a>，了解 oomd 如何在 Facebook 的生产环境中部署；该案例研究考察了 Facebook 的构建系统，这是 Facebook 上运行的最大服务之一。</p><h2 id="fbtax2-项目中的-oomd" tabindex="-1">fbtax2 项目中的 oomd <a class="header-anchor" href="#fbtax2-项目中的-oomd" aria-label="Permalink to “fbtax2 项目中的 oomd”">​</a></h2><div class="danger custom-block"><p>正如<a href="./ch011.html#the-fbtax2-memory-controller-configuration">前文</a>所述，<a href="./ch011.html#the-fbtax2-memory-controller-configuration">fbtax2 项目</a>团队通过使用 <code>memory.low</code> 为主工作负载的 cgroup <code>workload.slice</code> 提供软内存保证，从而优先保护主工作负载。在这种工作守恒模型中，<code>system.slice</code> 中的进程可以在主工作负载不需要时使用内存。</p><p>但存在一个问题：当 system.slice 中一个内存密集型进程由于 workload.slice 上的 memory.low 保护而无法再获取内存时，内存争用会转化为缺页引发的 IO 压力，这可能损害整体系统性能。</p><p><img src="/p002/ch01/003.png" alt="" width="662" height="108"></p><p>由于 system.slice 的 IO 控制器中设置的限制（我们将在本案例研究的<a href="./ch013.html#fbtax2-io-controller-configuration">下一节</a>中介绍），增加的 IO 压力会导致 <code>system.slice</code> 被节流。内核识别出减速是由内存不足引起的，<code>memory.pressure</code> 会相应上升。</p><p>oomd 监控压力，一旦超过配置的阈值，就杀死其中一个进程——很可能是 <code>system.slice</code> 中的内存占用大户——并在过高的内存压力导致系统崩溃之前解决该情况这种行为</p></div>`,24)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};